  func get_dict_size(_ c : UInt8) -> Int {
    var dict_size = 1 << (c & 0x1f)
    dict_size -= (dict_size >> 2) * ( (Int(c) >> 5) & 0x7)
    if (dict_size < MIN_DICTIONARY_SIZE || dict_size > MAX_DICTIONARY_SIZE) {
      return 0;
    }
    return dict_size;
  }

